/* ═══════════════════════════════════════════════════════════════════════════
   INSTALL STEPS — reusable install instructions component
═══════════════════════════════════════════════════════════════════════════ */
function InstallSteps({ accent = "#22c55e", compact = false }) {
  const ua = navigator.userAgent.toLowerCase();
  const isIos       = /iphone|ipad|ipod/i.test(ua);
  const isAndroid   = /android/i.test(ua);
  const isSafari    = /safari/i.test(ua) && !/chrome|crios|fxios/i.test(ua);
  const isChrome    = /chrome|crios/i.test(ua);
  const isInAppBrowser = /fbav|fban|instagram|twitter|line|wechat/i.test(ua);

  const [tab, setTab] = useState(isAndroid ? "android" : "iphone");

  // Wrong browser warnings
  const wrongBrowserWarning = () => {
    if (isInAppBrowser) {
      return {
        show: true,
        icon: "⚠️",
        color: "#f59e0b",
        text: "You're in an in-app browser. Tap the ··· menu and select \"Open in Safari\" (iPhone) or \"Open in Chrome\" (Android) first.",
      };
    }
    if (tab === "iphone" && isIos && !isSafari) {
      return {
        show: true,
        icon: "⚠️",
        color: "#f59e0b",
        text: "You need to open this page in Safari to install it. Copy the link below and paste it into Safari:",
      };
    }
    return { show: false };
  };

  const warning = wrongBrowserWarning();

  const iphoneSteps = [
    { icon:"🧭", text: isSafari || !isIos ? "Open jerseybasket.je in Safari" : "You're already in Safari ✓", done: isSafari },
    { icon:"⬆️", text:"Tap the Share button at the bottom of Safari" },
    { icon:"➕", text:"Scroll down and tap \"Add to Home Screen\"" },
    { icon:"✅", text:"Tap \"Add\" top right — the app icon appears on your home screen!" },
  ];

  const androidSteps = [
    { icon:"🌐", text: isChrome || !isAndroid ? "Open jerseybasket.je in Chrome" : "You're already in Chrome ✓", done: isChrome },
    { icon:"⋮",  text:"Tap the three dots ⋮ menu in the top right corner" },
    { icon:"➕", text:"Tap \"Add to Home Screen\"" },
    { icon:"✅", text:"Tap \"Add\" — the app icon appears on your home screen!" },
  ];

  const steps = tab === "iphone" ? iphoneSteps : androidSteps;

  const handleCopyLink = () => {
    navigator.clipboard.writeText("https://jerseybasket.je")
      .then(()=>alert("✅ Link copied! Now open Safari and paste it in the address bar."))
      .catch(()=>alert("Visit: https://jerseybasket.je"));
  };

  return (
    <div style={{ width:"100%", marginTop:16 }}>
      {/* tab switcher */}
      <div style={{ display:"flex", background:"rgba(0,0,0,.3)", borderRadius:10, padding:3, marginBottom:12, gap:3 }}>
        {[["iphone","🍎 iPhone / iPad"],["android","🤖 Android"]].map(([id,lbl])=>(
          <button key={id} onClick={()=>setTab(id)} style={{ flex:1, padding:compact?"5px 0":"7px 0", borderRadius:8, border:"none", cursor:"pointer", fontSize:compact?10:11, fontWeight:700,
            background: tab===id ? accent : "transparent",
            color: tab===id ? (accent==="#22c55e"?"#052e16":"#0a1628") : "rgba(255,255,255,.5)",
            transition:"all .2s" }}>
            {lbl}
          </button>
        ))}
      </div>

      {/* wrong browser warning */}
      {warning.show && (
        <div style={{ background:"rgba(245,158,11,.12)", border:"1px solid rgba(245,158,11,.35)", borderRadius:10, padding:"10px 12px", marginBottom:12, display:"flex", flexDirection:"column", gap:8 }}>
          <div style={{ fontSize:compact?10.5:12, color:"#fcd34d", lineHeight:1.5 }}>
            <span style={{ marginRight:6 }}>{warning.icon}</span>{warning.text}
          </div>
          {tab==="iphone" && isIos && !isSafari && (
            <button onClick={handleCopyLink} style={{ padding:"7px 12px", background:"rgba(245,158,11,.2)", border:"1px solid rgba(245,158,11,.4)", borderRadius:8, color:"#fcd34d", cursor:"pointer", fontSize:11, fontWeight:700 }}>
              📋 Copy jerseybasket.je link
            </button>
          )}
        </div>
      )}

      {/* steps */}
      <div style={{ display:"flex", flexDirection:"column", gap:compact?5:7 }}>
        {steps.map((step, i) => (
          <div key={i} style={{ display:"flex", alignItems:"center", gap:10,
            background: step.done ? "rgba(34,197,94,.12)" : "rgba(255,255,255,.06)",
            border: step.done ? "1px solid rgba(34,197,94,.25)" : "1px solid rgba(255,255,255,.06)",
            borderRadius:9, padding:compact?"7px 10px":"9px 12px" }}>
            <div style={{ width:compact?26:30, height:compact?26:30, borderRadius:7,
              background: step.done ? "rgba(34,197,94,.25)" : `${accent}22`,
              border:`1px solid ${step.done?"rgba(34,197,94,.4)":accent+"44"}`,
              display:"flex", alignItems:"center", justifyContent:"center",
              fontSize:compact?13:15, flexShrink:0 }}>
              {step.done ? "✓" : step.icon}
            </div>
            <div style={{ fontSize:compact?10.5:12, color: step.done?"#86efac":"rgba(255,255,255,.85)", fontWeight:step.done?600:500, lineHeight:1.4 }}>
              <span style={{ color: step.done?"#22c55e":accent, fontWeight:700, marginRight:5 }}>{i+1}.</span>
              {step.text}
            </div>
          </div>
        ))}
      </div>

      {/* direct link button */}
      {!compact && (
        <a href="https://jerseybasket.je" target="_blank" rel="noopener noreferrer"
          style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:8, marginTop:12,
            padding:"10px", background:"rgba(34,197,94,.12)", border:"1px solid rgba(34,197,94,.28)",
            borderRadius:10, color:"#22c55e", textDecoration:"none", fontSize:12, fontWeight:700 }}>
          🔗 jerseybasket.je — tap to open in browser
        </a>
      )}

      {!compact && (
        <div style={{ marginTop:10, fontSize:10, color:"rgba(255,255,255,.35)", textAlign:"center" }}>
          No App Store needed · Works offline · Always free
        </div>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   WELCOME SCREEN — shown once to first-time visitors
═══════════════════════════════════════════════════════════════════════════ */
function WelcomeModal({ onDismiss, lightMode=false }) {
  const [step, setStep] = useState(0);
  const [surveyAnswers, setSurveyAnswers] = useState({ q1: "", q2: "", q3: "", q4: "", q5: "" });
  const [surveySubmitted, setSurveySubmitted] = useState(false);
  const [surveySubmitting, setSurveySubmitting] = useState(false);
  const [qrZoomed, setQrZoomed] = useState(false);

  const handleSurveySelect = (q, val) => setSurveyAnswers(prev => ({ ...prev, [q]: prev[q] === val ? "" : val }));

  const submitSurvey = async () => {
    setSurveySubmitting(true);
    try {
      await fetch("https://formspree.io/f/mvzyrgqj", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          subject: "JerseyBasket App Survey Response",
          q1_ease: surveyAnswers.q1 || "No answer",
          q2_colour: surveyAnswers.q2 || "No answer",
          q3_improve: surveyAnswers.q3 || "No answer",
          q4_receipts: surveyAnswers.q4 || "No answer",
          q5_recommend: surveyAnswers.q5 || "No answer",
        }),
      });
      setSurveySubmitted(true);
    } catch(e) {
      setSurveySubmitted(true);
    }
    setSurveySubmitting(false);
  };

  const steps = [
    {
      emoji: "🛍️",
      title: "Welcome to JerseyBasket.je",
      subtitle: `Join 2,460+ Jersey shoppers saving money every week`,
      body: `Compare prices across all ${BASE_PRODUCTS.length} products and growing — find the cheapest price on every item and build your shopping list before you leave the house.`,
      bodyJsx: true,
      bg: "linear-gradient(135deg,#052e16 0%,#14532d 50%,#16a34a 100%)",
      bottomBg: "#052e16",
      accent: "#22c55e",
    },
    {
      emoji: "📲",
      title: "Scan & Share JerseyBasket",
      subtitle: "Show a friend in seconds",
      body: "Point your phone's camera at this code to open JerseyBasket.je instantly — perfect for showing a friend, family member, or fellow shopper in the queue.",
      bg: "linear-gradient(135deg,#0c2a1f 0%,#065f46 50%,#0d9488 100%)",
      bottomBg: "#0c2a1f",
      accent: "#5eead4",
      qr: true,
    },
    {
      emoji: "🏆",
      title: "Always the Cheapest Price First",
      subtitle: `${BASE_PRODUCTS.length}+ products across ${STORES.length} stores`,
      body: "Every product shows you the lowest price available in Jersey right now. Tap the store pill to compare all stores — or pin one store to see all their prices at once.",
      bg: "linear-gradient(135deg,#0c1445 0%,#1e3a8a 100%)",
      bottomBg: "#0c1445",
      accent: "#93c5fd",
    },
    {
      emoji: "🧺",
      title: "Build Your Shopping List",
      subtitle: "Smart basket with savings calculator",
      body: "Add items as you browse. The basket automatically works out which single store is cheapest for your whole shop — and shows exactly how much you'd save.",
      bg: "linear-gradient(135deg,#1a0533 0%,#581c87 100%)",
      bottomBg: "#1a0533",
      accent: "#c4b5fd",
    },
    {
      emoji: "♥",
      title: "Save Your Favourites",
      subtitle: "Heart items to save them for next time",
      body: "Tap the heart on any product to save it. Your favourites have their own basket — add them all in one tap every week. Your regular shop, sorted in seconds.",
      bg: "linear-gradient(135deg,#450a0a 0%,#991b1b 100%)",
      bottomBg: "#450a0a",
      accent: "#fca5a5",
    },
    {
      emoji: "📱",
      title: "Install it on Your Phone",
      subtitle: "Works like a native app — completely free",
      body: "Add JerseyBasket to your home screen in seconds:",
      bg: "linear-gradient(135deg,#0a1628 0%,#0d1f38 100%)",
      bottomBg: "#0a1628",
      accent: "#22c55e",
      installSteps: true,
    },
    {
      emoji: "✨",
      title: "Watch This Space!",
      subtitle: "Something new is on the way",
      body: "We're working on the next exciting thing for JerseyBasket shoppers — keep an eye out, more coming soon. 🇯🇪",
      bg: "linear-gradient(135deg,#0f0a2e 0%,#2d1a6b 60%,#4c1d95 100%)",
      bottomBg: "#0f0a2e",
      accent: "#c4b5fd",
    },
    {
      emoji: "📝",
      title: "Help Us Improve!",
      subtitle: "Your opinion shapes JerseyBasket",
      body: "",
      bg: "linear-gradient(135deg,#0f172a 0%,#1e3a5f 60%,#0c4a6e 100%)",
      bottomBg: "#0f172a",
      accent: "#38bdf8",
      survey: true,
    },
  ];

  const s = steps[step];
  const isLast = step === steps.length - 1;

  return (
    <div style={{ position:"fixed",inset:0,zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center",background:"rgba(0,0,0,.85)",backdropFilter:"blur(10px)",padding:16 }}>
      <div style={{ width:"100%",maxWidth:460,borderRadius:24,overflow:"hidden",boxShadow:"0 24px 80px rgba(0,0,0,.7)",display:"flex",flexDirection:"column",maxHeight:"90vh",background:s.bg,isolation:"isolate" }}>

        {/* slide — scrollable content area */}
        <div style={{ background:s.bg,padding:"40px 32px 32px",position:"relative",flex:1,overflowY:"auto",display:"flex",flexDirection:"column",alignItems:"center",textAlign:"center" }}>
          {/* skip button */}
          <button onClick={onDismiss} style={{ position:"absolute",top:16,right:16,background:"rgba(255,255,255,.1)",border:"none",borderRadius:7,padding:"4px 10px",color:"rgba(255,255,255,.5)",cursor:"pointer",fontSize:11,fontWeight:600 }}>
            Skip
          </button>

          {/* emoji / QR code */}
          {s.qr ? (
            <img
              src="/qr-jerseybasket.png"
              alt="Scan to open JerseyBasket.je"
              onClick={()=>setQrZoomed(z=>!z)}
              style={{ width:qrZoomed?220:130,height:qrZoomed?220:130,marginBottom:20,borderRadius:14,background:"#fff",padding:qrZoomed?12:8,cursor:"pointer",transition:"all .25s ease",boxShadow:"0 8px 24px rgba(0,0,0,.35)" }}
            />
          ) : (
            <div style={{ fontSize:64,marginBottom:20,lineHeight:1 }}>{s.emoji}</div>
          )}

          {/* title */}
          <div style={{ fontSize:22,fontWeight:700,color:"#fff",marginBottom:6,fontFamily:"'DM Serif Display',Georgia,serif",lineHeight:1.2 }}>
            {s.title}
          </div>

          {/* subtitle */}
          {step===0 && <style>{`@keyframes goldpulse{0%,100%{color:#f59e0b;transform:scale(1);box-shadow:0 0 8px rgba(245,158,11,.4),inset 0 0 8px rgba(245,158,11,.1)}50%{color:#fcd34d;transform:scale(1.04);box-shadow:0 0 18px rgba(252,211,77,.7),inset 0 0 12px rgba(252,211,77,.15)}}`}</style>}
          <div style={{ fontSize:12,fontWeight:700,marginBottom:16,textTransform:"uppercase",letterSpacing:"1px", ...(step===0 ? {animation:"goldpulse 2.8s ease-in-out infinite",display:"inline-block",color:"#f59e0b",border:"1.5px solid rgba(245,158,11,.7)",borderRadius:20,padding:"6px 18px",background:"rgba(245,158,11,.08)"} : {color:s.accent}) }}>
            {s.subtitle}
          </div>

          {/* body */}
          <div style={{ fontSize:13,color:"rgba(255,255,255,.8)",lineHeight:1.75,whiteSpace:"pre-line" }}>
            {s.bodyJsx ? (
              <>
                Compare prices across all{" "}
                <span style={{ fontFamily:"'DM Serif Display',Georgia,serif", fontSize:16, fontWeight:700, color:"#ffffff" }}>6</span>
                {" "}Jersey supermarkets instantly. Over{" "}
                <span style={{ fontFamily:"'DM Serif Display',Georgia,serif", fontSize:16, fontWeight:700, color:"#ffffff" }}>{BASE_PRODUCTS.length}</span>
                {" "}products and growing — find the cheapest price on every item and build your shopping list before you leave the house.
              </>
            ) : s.body}
          </div>

          {/* survey shortcut — only on slide 1 */}
          {step===0 && (
            <div style={{ marginTop:14, display:"flex", flexDirection:"column", alignItems:"center", gap:5 }}>
              <button onClick={()=>setStep(steps.length-1)} style={{ background:"linear-gradient(180deg,#fde047 0%,#eab308 100%)",border:"none",borderRadius:20,padding:"9px 20px",color:"#1a1400",fontSize:12.5,fontWeight:800,cursor:"pointer",position:"relative",overflow:"hidden",boxShadow:"0 3px 14px rgba(234,179,8,.55), inset 0 1px 0 rgba(255,255,255,.4)" }}>
                <span style={{ position:"absolute",top:0,left:0,right:0,height:"52%",background:"linear-gradient(180deg,rgba(255,255,255,.35) 0%,rgba(255,255,255,.05) 100%)",borderRadius:"20px 20px 0 0",pointerEvents:"none" }}/>
                💬 Help Us Help You — Take Our Survey
              </button>
              <div style={{ fontSize:10.5, color:"rgba(255,255,255,0.55)" }}>Your feedback shapes what we build next</div>
            </div>
          )}

          {/* install steps — only on install slide */}
          {s.installSteps && <InstallSteps accent={s.accent} />}

          {/* survey — only on survey slide */}
          {s.survey && (
            <div style={{ width:"100%",marginTop:8,textAlign:"left" }}>
              {surveySubmitted ? (
                <div style={{ textAlign:"center",padding:"24px 0" }}>
                  <div style={{ fontSize:48,marginBottom:12 }}>🙏</div>
                  <div style={{ fontSize:18,fontWeight:700,color:"#fff",marginBottom:8 }}>Survey Completed!</div>
                  <div style={{ fontSize:13,color:"rgba(255,255,255,.7)",lineHeight:1.7,marginBottom:24 }}>Your feedback helps us make JerseyBasket better for everyone in Jersey. 🇯🇪</div>
                  <button onClick={()=>{setStep(0);setSurveySubmitted(false);}} style={{ padding:"12px 32px",borderRadius:12,border:"none",background:"linear-gradient(135deg,#22c55e,#16a34a)",color:"#fff",fontSize:14,fontWeight:700,cursor:"pointer" }}>
                    Back to JerseyBasket 🛒
                  </button>
                </div>
              ) : (
                <>
                  {[
                    { q:"q1", label:"1️⃣ How easy is JerseyBasket to use?", opts:["😍 Love it","😊 Easy enough","😐 Takes getting used to","😕 Find it tricky"] },
                    { q:"q2", label:"2️⃣ What do you think of the colour scheme?", opts:["🌿 Love the dark green","☀️ Prefer something lighter","🤷 Don't mind either way"] },
                    { q:"q3", label:"3️⃣ What would you most like improved?", opts:["🔍 Better search","📦 More products","💰 More stores","📱 Easier to use"] },
                    { q:"q4", label:"4️⃣ What would make you submit more receipts?", opts:["🏆 Bigger prizes","📱 Easier submission","⏰ More reminders","✅ I already do!"] },
                    { q:"q5", label:"5️⃣ Would you recommend JerseyBasket?", opts:["👍 Already have!","👀 Haven't yet but will","🤔 Not sure yet"] },
                  ].map(({ q, label, opts }) => (
                    <div key={q} style={{ marginBottom:16 }}>
                      <div style={{ fontSize:12,fontWeight:700,color:"#38bdf8",marginBottom:8,lineHeight:1.4 }}>{label}</div>
                      <div style={{ display:"flex",flexDirection:"column",gap:6 }}>
                        {opts.map(opt => (
                          <button key={opt} onClick={() => handleSurveySelect(q, opt)} style={{ textAlign:"left",padding:"9px 14px",borderRadius:10,border:`1.5px solid ${surveyAnswers[q]===opt?"#38bdf8":"rgba(255,255,255,.15)"}`,background:surveyAnswers[q]===opt?"rgba(56,189,248,.2)":"rgba(255,255,255,.05)",color:surveyAnswers[q]===opt?"#fff":"rgba(255,255,255,.75)",fontSize:12,fontWeight:surveyAnswers[q]===opt?700:400,cursor:"pointer",display:"flex",alignItems:"center",gap:8,transition:"all .2s" }}>
                            <div style={{ width:16,height:16,borderRadius:4,border:`2px solid ${surveyAnswers[q]===opt?"#38bdf8":"rgba(255,255,255,.3)"}`,background:surveyAnswers[q]===opt?"#38bdf8":"transparent",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center" }}>
                              {surveyAnswers[q]===opt && <div style={{ width:8,height:8,borderRadius:2,background:"#0f172a" }}/>}
                            </div>
                            {opt}
                          </button>
                        ))}
                      </div>
                    </div>
                  ))}
                  <button onClick={submitSurvey} disabled={surveySubmitting} style={{ width:"100%",marginTop:8,padding:"13px",borderRadius:12,border:"none",background:"linear-gradient(135deg,#0ea5e9,#0284c7)",color:"#fff",fontSize:14,fontWeight:700,cursor:"pointer",opacity:surveySubmitting?0.7:1 }}>
                    {surveySubmitting ? "Sending..." : "Submit My Feedback 📝"}
                  </button>
                  <button onClick={onDismiss} style={{ width:"100%",marginTop:8,padding:"10px",borderRadius:12,border:"1px solid rgba(255,255,255,.1)",background:"transparent",color:"rgba(255,255,255,.4)",fontSize:12,cursor:"pointer" }}>
                    Skip survey
                  </button>
                </>
              )}
            </div>
          )}

          {/* decorative glow */}
          <div style={{ position:"absolute",bottom:-40,left:"50%",transform:"translateX(-50%)",width:200,height:200,borderRadius:"50%",background:`${s.accent}22`,pointerEvents:"none",filter:"blur(40px)" }} />
        </div>

        {/* bottom controls — sticky so always visible */}
        <div style={{ background:s.bottomBg||"#052e16",padding:"20px 24px 24px",display:"flex",flexDirection:"column",gap:16,flexShrink:0 }}>
          {/* dots */}
          <div style={{ display:"flex",justifyContent:"center",gap:6 }}>
            {steps.map((_,i)=>(
              <div key={i} onClick={()=>setStep(i)} style={{ width:i===step?20:6,height:6,borderRadius:3,background:i===step?s.accent:"rgba(255,255,255,.2)",cursor:"pointer",transition:"all .3s",boxShadow:i===step?`0 0 8px ${s.accent}88`:"none" }} />
            ))}
          </div>

          {/* buttons */}
          <div style={{ display:"flex",gap:10 }}>
            {step > 0 && (
              <button onClick={()=>setStep(s=>s-1)} style={{ flex:1,padding:"12px",background:"linear-gradient(180deg,#1e3a5f 0%,#0f1f3d 100%)",border:"1px solid rgba(125,211,252,0.2)",borderRadius:12,color:"#7dd3fc",cursor:"pointer",fontSize:13,fontWeight:700,position:"relative",overflow:"hidden",boxShadow:"0 2px 8px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.08)" }}>
                <span style={{ position:"absolute",top:0,left:0,right:0,height:"52%",background:"linear-gradient(180deg,rgba(255,255,255,.12) 0%,rgba(255,255,255,.02) 100%)",borderRadius:"12px 12px 0 0",pointerEvents:"none" }}/>
                ← Back
              </button>
            )}
            <button
              onClick={isLast ? onDismiss : ()=>setStep(s=>s+1)}
              style={{ flex:2,padding:"12px",background:`linear-gradient(180deg,${s.accent} 0%,${s.accent}99 100%)`,border:"none",borderRadius:12,color:"#052e16",cursor:"pointer",fontSize:14,fontWeight:700,position:"relative",overflow:"hidden",boxShadow:`0 3px 12px ${s.accent}66, inset 0 1px 0 rgba(255,255,255,.3)` }}>
              <span style={{ position:"absolute",top:0,left:0,right:0,height:"52%",background:"linear-gradient(180deg,rgba(255,255,255,.28) 0%,rgba(255,255,255,.04) 100%)",borderRadius:"12px 12px 0 0",pointerEvents:"none" }}/>
              {isLast ? "🛒 Start Saving Now →" : "Next →"}
            </button>
          </div>

          {/* jersey flag note */}
          <div style={{ textAlign:"center",fontSize:10,color:"rgba(255,255,255,0.7)" }}>
            🇯🇪 Built for Jersey · Free forever · jerseybasket.je
          </div>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   PWA REFRESH NOTICE — one-time, standalone-mode-only nudge shown after the
   welcome screen closes. Covers the gap the service worker itself can't:
   an icon that's fully stuck on a pre-service-worker snapshot may never
   fetch fresh HTML on its own to pick up the new auto-update code, so
   existing installs need one manual reset before they self-heal.
═══════════════════════════════════════════════════════════════════════════ */
function PwaRefreshNotice({ onClose, lightMode=false }) {
  return (
    <div style={{ position:"fixed",inset:0,zIndex:500,display:"flex",alignItems:"center",justifyContent:"center",background:"rgba(0,0,0,.75)",backdropFilter:"blur(8px)",padding:16 }}
      onClick={e=>{ if(e.target===e.currentTarget) onClose(); }}>
      <div style={{ width:"100%",maxWidth:420,background:lightMode?"rgba(240,244,248,.98)":"#0a1a30",border:lightMode?"1px solid rgba(0,0,0,.12)":"1px solid rgba(255,255,255,.12)",borderRadius:20,padding:"22px 20px 20px" }}>
        <div style={{ fontSize:34,textAlign:"center",marginBottom:10 }}>📲</div>
        <div style={{ fontSize:16,fontWeight:700,color:lightMode?"#0f172a":"#f0f4f8",textAlign:"center",marginBottom:8 }}>
          One-time home screen refresh
        </div>
        <div style={{ fontSize:12.5,color:"#64748b",lineHeight:1.6,textAlign:"center",marginBottom:16 }}>
          JerseyBasket keeps growing fast, and your home screen icon may be a version or two behind. Do this once and it'll stay current automatically from now on:
        </div>
        <div style={{ display:"flex",flexDirection:"column",gap:10,marginBottom:18 }}>
          {[
            ["1","Delete the JerseyBasket icon from your home screen"],
            ["2","Open jerseybasket.je fresh in Safari (iPhone) or Chrome (Android)"],
            ["3","Add it to your home screen again"],
          ].map(([n,text])=>(
            <div key={n} style={{ display:"flex",gap:10,alignItems:"flex-start" }}>
              <div style={{ width:22,height:22,borderRadius:"50%",background:"rgba(34,197,94,.15)",border:"1px solid rgba(34,197,94,.35)",color:"#22c55e",fontSize:11,fontWeight:700,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0 }}>{n}</div>
              <div style={{ fontSize:12.5,color:lightMode?"#1e293b":"#e2e8f0",lineHeight:1.5 }}>{text}</div>
            </div>
          ))}
        </div>
        <button onClick={onClose} style={{ width:"100%",padding:"12px",background:"linear-gradient(180deg,#4ade80 0%,#15803d 100%)",boxShadow:"0 3px 10px rgba(34,197,94,.5),inset 0 1px 0 rgba(255,255,255,.3)",border:"none",borderRadius:11,color:"#fff",cursor:"pointer",fontSize:13,fontWeight:700 }}>
          Got it
        </button>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   TIPS MODAL — swipeable "how to use the app" carousel, opened from the
   home screen banner (and, later, from a permanent Tips button)
═══════════════════════════════════════════════════════════════════════════ */
function TipsModal({ onClose, lightMode=false }) {
  const [step, setStep] = useState(0);

  const steps = [
    {
      emoji: "🏆",
      title: "Always See the Cheapest Price",
      subtitle: `${BASE_PRODUCTS.length}+ products, 6 stores, one price shown first`,
      body: "Every product automatically shows you the lowest price in Jersey right now. Tap the store pill on any item to see how all 6 stores compare, ranked cheapest to most expensive.",
      bg: "linear-gradient(135deg,#0c1445 0%,#1e3a8a 100%)",
      bottomBg: "#0c1445",
      accent: "#93c5fd",
    },
    {
      emoji: "📌",
      title: "Pin Your Usual Store",
      subtitle: "See one store's prices for everything at once",
      body: "Tap a store chip at the top of the screen to pin it. Every product will then show that store's price first — perfect if you always shop in the same place but still want to spot better deals elsewhere.",
      bg: "linear-gradient(135deg,#052e16 0%,#14532d 50%,#16a34a 100%)",
      bottomBg: "#052e16",
      accent: "#22c55e",
    },
    {
      emoji: "🧺",
      title: "Let the Basket Do the Maths",
      subtitle: "Smart basket with a savings calculator",
      body: "Add items as you browse, from any store. The basket automatically works out which single store is cheapest for your whole shop — and shows exactly how much you'd save versus the most expensive option.",
      bg: "linear-gradient(135deg,#1a0533 0%,#581c87 100%)",
      bottomBg: "#1a0533",
      accent: "#c4b5fd",
    },
    {
      emoji: "♥",
      title: "Save Your Regular Shop",
      subtitle: "Heart items to build a reusable favourites list",
      body: "Tap the heart on any product to save it. Your favourites have their own basket — add them all in one tap every week instead of searching for the same items again and again.",
      bg: "linear-gradient(135deg,#450a0a 0%,#991b1b 100%)",
      bottomBg: "#450a0a",
      accent: "#fca5a5",
    },
    {
      emoji: "🔍",
      title: "Search, Sort & Browse by Category",
      subtitle: "Find anything in seconds",
      body: "Search across all products instantly, or sort by cheapest price, biggest saving, A–Z, or category — whichever makes your shop easier.",
      bg: "linear-gradient(135deg,#0f172a 0%,#1e3a5f 60%,#0c4a6e 100%)",
      bottomBg: "#0f172a",
      accent: "#38bdf8",
    },
    {
      emoji: "📱",
      title: "Install it on Your Phone",
      subtitle: "Works like a native app — completely free",
      body: "Add JerseyBasket to your home screen in seconds:",
      bg: "linear-gradient(135deg,#0a1628 0%,#0d1f38 100%)",
      bottomBg: "#0a1628",
      accent: "#22c55e",
      installSteps: true,
    },
  ];

  const s = steps[step];
  const isLast = step === steps.length - 1;

  return (
    <div style={{ position:"fixed",inset:0,zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center",background:"rgba(0,0,0,.85)",backdropFilter:"blur(10px)",padding:16 }}>
      <div style={{ width:"100%",maxWidth:460,borderRadius:24,overflow:"hidden",boxShadow:"0 24px 80px rgba(0,0,0,.7)",display:"flex",flexDirection:"column",maxHeight:"90vh",background:s.bg,isolation:"isolate" }}>

        {/* slide — scrollable content area */}
        <div style={{ background:s.bg,padding:"40px 32px 32px",position:"relative",flex:1,overflowY:"auto",display:"flex",flexDirection:"column",alignItems:"center",textAlign:"center" }}>
          {/* close button */}
          <button onClick={onClose} style={{ position:"absolute",top:16,right:16,background:"rgba(255,255,255,.1)",border:"none",borderRadius:7,padding:"4px 10px",color:"rgba(255,255,255,.5)",cursor:"pointer",fontSize:11,fontWeight:600 }}>
            Close
          </button>

          {/* emoji */}
          <div style={{ fontSize:64,marginBottom:20,lineHeight:1 }}>{s.emoji}</div>

          {/* title */}
          <div style={{ fontSize:22,fontWeight:700,color:"#fff",marginBottom:6,fontFamily:"'DM Serif Display',Georgia,serif",lineHeight:1.2 }}>
            {s.title}
          </div>

          {/* subtitle */}
          <div style={{ fontSize:12,fontWeight:700,marginBottom:16,textTransform:"uppercase",letterSpacing:"1px",color:s.accent }}>
            {s.subtitle}
          </div>

          {/* body */}
          <div style={{ fontSize:13,color:"rgba(255,255,255,.8)",lineHeight:1.75,whiteSpace:"pre-line" }}>
            {s.body}
          </div>

          {/* install steps — only on install slide */}
          {s.installSteps && <InstallSteps accent={s.accent} />}

          {/* decorative glow */}
          <div style={{ position:"absolute",bottom:-40,left:"50%",transform:"translateX(-50%)",width:200,height:200,borderRadius:"50%",background:`${s.accent}22`,pointerEvents:"none",filter:"blur(40px)" }} />
        </div>

        {/* bottom controls — sticky so always visible */}
        <div style={{ background:s.bottomBg||"#052e16",padding:"20px 24px 24px",display:"flex",flexDirection:"column",gap:16,flexShrink:0 }}>
          {/* dots */}
          <div style={{ display:"flex",justifyContent:"center",gap:6 }}>
            {steps.map((_,i)=>(
              <div key={i} onClick={()=>setStep(i)} style={{ width:i===step?20:6,height:6,borderRadius:3,background:i===step?s.accent:"rgba(255,255,255,.2)",cursor:"pointer",transition:"all .3s",boxShadow:i===step?`0 0 8px ${s.accent}88`:"none" }} />
            ))}
          </div>

          {/* buttons */}
          <div style={{ display:"flex",gap:10 }}>
            {step > 0 && (
              <button onClick={()=>setStep(s=>s-1)} style={{ flex:1,padding:"12px",background:"linear-gradient(180deg,#1e3a5f 0%,#0f1f3d 100%)",border:"1px solid rgba(125,211,252,0.2)",borderRadius:12,color:"#7dd3fc",cursor:"pointer",fontSize:13,fontWeight:700,position:"relative",overflow:"hidden",boxShadow:"0 2px 8px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.08)" }}>
                <span style={{ position:"absolute",top:0,left:0,right:0,height:"52%",background:"linear-gradient(180deg,rgba(255,255,255,.12) 0%,rgba(255,255,255,.02) 100%)",borderRadius:"12px 12px 0 0",pointerEvents:"none" }}/>
                ← Back
              </button>
            )}
            <button
              onClick={isLast ? onClose : ()=>setStep(s=>s+1)}
              style={{ flex:2,padding:"12px",background:`linear-gradient(180deg,${s.accent} 0%,${s.accent}99 100%)`,border:"none",borderRadius:12,color:"#052e16",cursor:"pointer",fontSize:14,fontWeight:700,position:"relative",overflow:"hidden",boxShadow:`0 3px 12px ${s.accent}66, inset 0 1px 0 rgba(255,255,255,.3)` }}>
              <span style={{ position:"absolute",top:0,left:0,right:0,height:"52%",background:"linear-gradient(180deg,rgba(255,255,255,.28) 0%,rgba(255,255,255,.04) 100%)",borderRadius:"12px 12px 0 0",pointerEvents:"none" }}/>
              {isLast ? "🛒 Got It →" : "Next →"}
            </button>
          </div>

          {/* jersey flag note */}
          <div style={{ textAlign:"center",fontSize:10,color:"rgba(255,255,255,0.7)" }}>
            🇯🇪 Built for Jersey · Free forever · jerseybasket.je
          </div>
        </div>
      </div>
    </div>
  );
}

