/* ═══════════════════════════════════════════════════════════════════════════
   REPORT PROBLEM MODAL
═══════════════════════════════════════════════════════════════════════════ */
function ReportModal({ onClose, lightMode=false }) {
  const [form,   setForm]   = useState({ type:"wrong_price", product:"", detail:"" });
  const [status, setStatus] = useState("idle");

  const TYPES = [
    { id:"wrong_price",   label:"💰 Wrong price",          placeholder:"e.g. Co-op Full Fat Milk 2L shows £1.75 but it's actually £1.95" },
    { id:"missing_item",  label:"➕ Missing product",       placeholder:"e.g. Oat Milk 1L is not listed anywhere" },
    { id:"store_issue",   label:"🏪 Store info wrong",      placeholder:"e.g. Waitrose is showing wrong location" },
    { id:"app_problem",   label:"🐛 App not working right", placeholder:"e.g. The basket total is calculating incorrectly" },
    { id:"other",         label:"💬 Other feedback",        placeholder:"Tell us anything you'd like to improve" },
  ];

  const selectedType = TYPES.find(t=>t.id===form.type);

  const handleSubmit = async () => {
    if(!form.detail.trim()){return;}
    setStatus("sending");
    try {
      const res = await fetch(`https://formspree.io/f/${FORMSPREE_ID}`,{
        method:"POST",
        headers:{"Content-Type":"application/json","Accept":"application/json"},
        body: JSON.stringify({
          _subject: `Problem Report — JerseyBasket.je`,
          type: selectedType?.label,
          product: form.product || "Not specified",
          detail: form.detail,
          message: `PROBLEM REPORT\n\nType: ${selectedType?.label}\nProduct: ${form.product||"Not specified"}\nDetails: ${form.detail}`,
        })
      });
      if(res.ok){ setStatus("sent"); }
      else { setStatus("error"); }
    } catch { setStatus("error"); }
  };

  return (
    <div style={{ position:"fixed",inset:0,zIndex:500,display:"flex",alignItems:"flex-end",justifyContent:"center",paddingTop:60,background:"rgba(0,0,0,.75)",backdropFilter:"blur(8px)" }}
      onClick={e=>{ if(e.target===e.currentTarget) onClose(); }}>
      <div style={{ width:"100%",maxWidth:520,background:lightMode?"rgba(240,244,248,.98)":"#0a1a30",border:lightMode?"1px solid rgba(0,0,0,.12)":"1px solid rgba(255,255,255,.12)",borderRadius:"20px 20px 0 0",padding:"22px 20px 30px",maxHeight:"82vh",overflowY:"auto",paddingBottom:"calc(132px + 32px)" }}>

        {status==="sent" ? (
          <div style={{ textAlign:"center",padding:"30px 0" }}>
            <div style={{ fontSize:44,marginBottom:14 }}>🙏</div>
            <div style={{ fontSize:17,fontWeight:700,color:"#22c55e",marginBottom:8 }}>Thanks for the report!</div>
            <div style={{ fontSize:12,color:"#94a3b8",lineHeight:1.7,marginBottom:22 }}>
              We'll look into it and fix it as soon as possible.<br/>
              JerseyBasket is better because of people like you.
            </div>
            <button onClick={onClose} style={{ padding:"10px 28px",background:"linear-gradient(180deg,#4ade80 0%,#15803d 100%)",boxShadow:"0 3px 10px rgba(34,197,94,.5),inset 0 1px 0 rgba(255,255,255,.3)",border:"none",borderRadius:11,color:"#fff",cursor:"pointer",fontSize:13,fontWeight:700 }}>
              Back to App
            </button>
          </div>
        ) : (
          <>
            <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16 }}>
              <div>
                <div style={{ fontSize:17,fontWeight:700,color:"#f0f4f8" }}>🚩 Report a Problem</div>
                <div style={{ fontSize:11,color:lightMode?'#334155':"#64748b",marginTop:2 }}>Help us keep JerseyBasket accurate</div>
              </div>
              <button onClick={onClose} style={{ background:"rgba(255,255,255,.07)",border:"none",borderRadius:7,width:28,height:28,color:"#94a3b8",cursor:"pointer",fontSize:14 }}>✕</button>
            </div>

            {/* problem type */}
            <div style={{ marginBottom:14 }}>
              <div style={{ fontSize:10,color:"#64748b",fontWeight:700,letterSpacing:".5px",marginBottom:8 }}>WHAT'S THE PROBLEM?</div>
              <div style={{ display:"flex",flexDirection:"column",gap:6 }}>
                {TYPES.map(t=>(
                  <button key={t.id} onClick={()=>setForm(p=>({...p,type:t.id}))}
                    style={{ padding:"9px 13px",borderRadius:9,border:`1px solid ${form.type===t.id?"rgba(34,197,94,.4)":"rgba(255,255,255,.08)"}`,background:form.type===t.id?"rgba(34,197,94,.12)":"rgba(255,255,255,.04)",color:form.type===t.id?"#86efac":"#94a3b8",cursor:"pointer",fontSize:12,fontWeight:form.type===t.id?700:400,textAlign:"left",transition:"all .15s" }}>
                    {t.label}
                  </button>
                ))}
              </div>
            </div>

            {/* product name (optional) */}
            <div style={{ marginBottom:12 }}>
              <div style={{ fontSize:10,color:"#64748b",fontWeight:700,letterSpacing:".5px",marginBottom:6 }}>PRODUCT NAME <span style={{ color:"#334155",fontWeight:400 }}>(optional)</span></div>
              <input value={form.product} onChange={e=>setForm(p=>({...p,product:e.target.value}))} placeholder="e.g. Full Fat Milk 2L"
                style={{ width:"100%",padding:"9px 12px",background:"rgba(255,255,255,.07)",border:"1px solid rgba(255,255,255,.11)",borderRadius:9,color:"#fff",fontSize:12,outline:"none",boxSizing:"border-box" }} />
            </div>

            {/* detail */}
            <div style={{ marginBottom:14 }}>
              <div style={{ fontSize:10,color:"#64748b",fontWeight:700,letterSpacing:".5px",marginBottom:6 }}>DETAILS <span style={{ color:"#f43f5e" }}>*</span></div>
              <textarea value={form.detail} onChange={e=>setForm(p=>({...p,detail:e.target.value}))} rows={3}
                placeholder={selectedType?.placeholder}
                style={{ width:"100%",padding:"9px 12px",background:"rgba(255,255,255,.07)",border:`1px solid ${!form.detail.trim()&&status==="error"?"rgba(239,68,68,.5)":"rgba(255,255,255,.11)"}`,borderRadius:9,color:"#fff",fontSize:12,outline:"none",resize:"none",boxSizing:"border-box",fontFamily:"inherit",lineHeight:1.5 }} />
            </div>

            {status==="error"&&<div style={{ background:"rgba(239,68,68,.1)",border:"1px solid rgba(239,68,68,.28)",borderRadius:8,padding:"7px 12px",fontSize:11,color:"#fca5a5",marginBottom:12 }}>Something went wrong. Please email hello@jerseybasket.je</div>}

            <button onClick={handleSubmit} disabled={!form.detail.trim()||status==="sending"}
              style={{ width:"100%",padding:"12px",background:!form.detail.trim()||status==="sending"?"rgba(34,197,94,.3)":"linear-gradient(135deg,#16a34a,#15803d)",border:"none",borderRadius:12,color:"#fff",cursor:!form.detail.trim()?"not-allowed":"pointer",fontSize:14,fontWeight:700 }}>
              {status==="sending" ? "Sending…" : "Send Report →"}
            </button>
          </>
        )}
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   ENQUIRY MODAL — friendly in-app contact form, no email client needed
═══════════════════════════════════════════════════════════════════════════ */
function EnquiryModal({ onClose, lightMode=false }) {
  const [form,    setForm]    = useState({ name:"", business:"", email:"", message:"I am interested in advertising on JerseyBasket.je. Please send me more information about available banner slots and pricing." });
  const [status,  setStatus]  = useState("idle"); // idle | sending | sent | error
  const [touched, setTouched] = useState({});

  const valid = form.name.trim() && form.email.includes("@") && form.message.trim();

  const handleSubmit = async () => {
    setTouched({ name:true, email:true, message:true });
    if (!valid) return;
    setStatus("sending");
    try {
      // Formspree — free tier handles 50 submissions/month
      // Replace YOUR_FORM_ID with your Formspree form ID (free at formspree.io)
      const res = await fetch(`https://formspree.io/f/${FORMSPREE_ID}`, {
        method:"POST",
        headers:{ "Content-Type":"application/json", "Accept":"application/json" },
        body: JSON.stringify({
          name:     form.name,
          business: form.business,
          email:    form.email,
          message:  form.message,
          _subject: "Banner Advertising Enquiry — JerseyBasket.je",
        })
      });
      if (res.ok) { setStatus("sent"); }
      else        { setStatus("error"); }
    } catch {
      setStatus("error");
    }
  };

  const field = (key, label, placeholder, type="text", rows=0) => (
    <div style={{ marginBottom:12 }}>
      <label style={{ display:"block", fontSize:10, fontWeight:700, letterSpacing:".5px", textTransform:"uppercase", color:"#64748b", marginBottom:5 }}>
        {label}{key!=="business"&&<span style={{ color:"#f43f5e" }}> *</span>}
      </label>
      {rows > 0 ? (
        <textarea
          value={form[key]}
          onChange={e=>setForm(p=>({...p,[key]:e.target.value}))}
          onBlur={()=>setTouched(p=>({...p,[key]:true}))}
          rows={rows}
          placeholder={placeholder}
          style={{ width:"100%", padding:"9px 12px", background:"rgba(255,255,255,.07)", border:`1px solid ${touched[key]&&!form[key].trim()?"rgba(244,63,94,.5)":"rgba(255,255,255,.12)"}`, borderRadius:9, color:"#fff", fontSize:12, outline:"none", resize:"none", boxSizing:"border-box", fontFamily:"inherit", lineHeight:1.5 }}
        />
      ) : (
        <input
          type={type}
          value={form[key]}
          onChange={e=>setForm(p=>({...p,[key]:e.target.value}))}
          onBlur={()=>setTouched(p=>({...p,[key]:true}))}
          placeholder={placeholder}
          style={{ width:"100%", padding:"9px 12px", background:"rgba(255,255,255,.07)", border:`1px solid ${touched[key]&&(key==="email"?!form[key].includes("@"):!form[key].trim())?"rgba(244,63,94,.5)":"rgba(255,255,255,.12)"}`, borderRadius:9, color:"#fff", fontSize:12, outline:"none", boxSizing:"border-box" }}
        />
      )}
      {touched[key] && key!=="business" && (key==="email" ? !form.email.includes("@") : !form[key].trim()) && (
        <div style={{ fontSize:10, color:"#f87171", marginTop:3 }}>Required</div>
      )}
    </div>
  );

  return (
    <div style={{ position:"fixed", inset:0, zIndex:500, display:"flex", alignItems:"center", justifyContent:"center", background:"rgba(0,0,0,.75)", backdropFilter:"blur(8px)", padding:"16px", overflowY:"auto" }}
      onClick={e=>{ if(e.target===e.currentTarget) onClose(); }}>
      <div style={{ position:"relative", width:"100%", maxWidth:520, background:lightMode?"rgba(240,244,248,.98)":"#0a1a30", border:lightMode?"1px solid rgba(0,0,0,.12)":"1px solid rgba(255,255,255,.12)", borderRadius:20, maxHeight:"90vh", display:"flex", flexDirection:"column", margin:"auto" }}>
        {/* Sticky close button */}
        <div style={{ position:"sticky", top:0, zIndex:10, display:"flex", justifyContent:"flex-end", padding:"12px 14px 0", background:lightMode?"rgba(240,244,248,.98)":"#0a1a30", borderRadius:"20px 20px 0 0", flexShrink:0 }}>
          <button onClick={onClose} style={{ background:"rgba(255,255,255,.07)", border:"none", borderRadius:7, width:32, height:32, color:"#94a3b8", cursor:"pointer", fontSize:16, display:"flex", alignItems:"center", justifyContent:"center" }}>✕</button>
        </div>
        <div style={{ overflowY:"auto", padding:"8px 20px 28px" }}>

        {status === "sent" ? (
          <div style={{ textAlign:"center", padding:"30px 10px" }}>
            <div style={{ fontSize:48, marginBottom:16 }}>🎉</div>
            <div style={{ fontSize:20, fontWeight:700, color:"#22c55e", marginBottom:8 }}>Enquiry Sent!</div>
            <div style={{ fontSize:13, color:"#94a3b8", lineHeight:1.7, marginBottom:24 }}>
              Thanks for your interest in advertising on JerseyBasket.je.<br/>
              Eamonn will be in touch shortly at <strong style={{ color:"#f0f4f8" }}>{form.email}</strong>
            </div>
            <button onClick={onClose} style={{ padding:"10px 28px", background:"linear-gradient(180deg,#4ade80 0%,#15803d 100%)",boxShadow:"0 3px 10px rgba(34,197,94,.5),inset 0 1px 0 rgba(255,255,255,.3)", border:"none", borderRadius:11, color:"#fff", cursor:"pointer", fontSize:13, fontWeight:700 }}>
              Back to App
            </button>
          </div>
        ) : (
          <>
            {/* header */}
            <div style={{ marginBottom:20 }}>
                <div style={{ fontSize:18, fontWeight:700, color:lightMode?'#0f172a':"#f0f4f8", marginBottom:3 }}>📢 Advertise on JerseyBasket.je</div>
                <div style={{ fontSize:11, color:"#64748b", lineHeight:1.6 }}>
                  Reach Jersey's grocery shoppers every day.<br/>
                  Banner slots from <strong style={{ color:"#22c55e" }}>£99/month</strong> — limited availability.
                </div>
            </div>

            {/* stats row */}
            <div style={{ display:"flex", gap:8, marginBottom:20 }}>
              {[[`${BASE_PRODUCTS.length}+`,"products listed"],[`${STORES.length}`,"stores compared"],["Jersey","audience only"],["Daily","active users"]].map(([val,lbl])=>(
                <div key={lbl} style={{ flex:1, background:"rgba(34,197,94,.08)", border:"1px solid rgba(34,197,94,.15)", borderRadius:9, padding:"7px 4px", textAlign:"center" }}>
                  <div style={{ fontSize:13, fontWeight:700, color:"#22c55e" }}>{val}</div>
                  <div style={{ fontSize:8, color:"#64748b", marginTop:1, textTransform:"uppercase", letterSpacing:".5px" }}>{lbl}</div>
                </div>
              ))}
            </div>

            {/* form */}
            {field("name",     "Your Name",     "e.g. John Smith")}
            {field("business", "Business Name (optional)", "e.g. Smith's Bakery, St Helier")}
            {field("email",    "Email Address", "e.g. john@yourbusiness.je", "email")}
            {field("message",  "Message",       "Tell us about your business...", "text", 3)}

            {status === "error" && (
              <div style={{ background:"rgba(239,68,68,.1)", border:"1px solid rgba(239,68,68,.28)", borderRadius:8, padding:"8px 12px", fontSize:11, color:"#fca5a5", marginBottom:12 }}>
                Something went wrong. Please email us directly at <strong>hello@jerseybasket.je</strong>
              </div>
            )}

            <button
              onClick={handleSubmit}
              disabled={status==="sending"}
              style={{ width:"100%", padding:"13px", background:status==="sending"?"rgba(34,197,94,.4)":"linear-gradient(135deg,#16a34a,#15803d)", border:"none", borderRadius:12, color:"#fff", cursor:status==="sending"?"wait":"pointer", fontSize:14, fontWeight:700, transition:"all .2s" }}>
              {status==="sending" ? "Sending…" : "Send Enquiry →"}
            </button>

            <div style={{ textAlign:"center", fontSize:10, color:"#334155", marginTop:10 }}>
              Or email directly: <a href="mailto:hello@jerseybasket.je" style={{ color:"#22c55e" }}>hello@jerseybasket.je</a>
            </div>
          </>
        )}
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   SETTINGS MODAL — store on/off toggles
═══════════════════════════════════════════════════════════════════════════ */
function SettingsModal({ disabledStores, onToggleStore, onClose, lightMode=false }) {
  return (
    <div style={{ position:"fixed",inset:0,zIndex:500,display:"flex",alignItems:"center",justifyContent:"center",background:"rgba(0,0,0,.75)",backdropFilter:"blur(8px)",padding:16,overflowY:"auto" }}
      onClick={e=>{ if(e.target===e.currentTarget) onClose(); }}>
      <div style={{ position:"relative",width:"100%",maxWidth:520,background:lightMode?"rgba(240,244,248,.98)":"#0a1a30",border:lightMode?"1px solid rgba(0,0,0,.12)":"1px solid rgba(255,255,255,.12)",borderRadius:20,maxHeight:"85vh",display:"flex",flexDirection:"column",margin:"auto" }}>

        {/* sticky header — always visible regardless of scroll */}
        <div style={{ display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexShrink:0,padding:"20px 20px 16px",borderRadius:"20px 20px 0 0",background:lightMode?"rgba(240,244,248,.98)":"#0a1a30" }}>
          <div>
            <div style={{ fontSize:17,fontWeight:700,color:"#f0f4f8" }}>⚙️ Settings</div>
            <div style={{ fontSize:11,color:"#64748b",marginTop:2 }}>Hide stores you don't want to see</div>
          </div>
          <button onClick={onClose} style={{ background:"rgba(255,255,255,.07)",border:"none",borderRadius:7,width:32,height:32,color:"#94a3b8",cursor:"pointer",fontSize:16,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0 }}>✕</button>
        </div>

        {/* scrollable content */}
        <div style={{ overflowY:"auto",padding:"0 20px 20px" }}>

        {/* store toggles */}
        <div style={{ fontSize:10,color:"#64748b",fontWeight:700,letterSpacing:".5px",marginBottom:10 }}>SHOW / HIDE STORES</div>
        <div style={{ display:"flex",flexDirection:"column",gap:8,marginBottom:20 }}>
          {STORES.map(store => {
            const enabled = !disabledStores.has(store.id);
            return (
              <div key={store.id} onClick={()=>onToggleStore(store.id)}
                style={{ display:"flex",alignItems:"center",justifyContent:"space-between",padding:"13px 16px",borderRadius:12,cursor:"pointer",
                  background:enabled?`${store.color}12`:"rgba(255,255,255,.03)",
                  border:`1px solid ${enabled?store.color+"40":"rgba(255,255,255,.07)"}`,
                  opacity:enabled?1:0.5, transition:"all .2s" }}>
                <div style={{ display:"flex",alignItems:"center",gap:10 }}>
                  <span style={{ fontSize:20 }}>{store.emoji}</span>
                  <div>
                    <div style={{ display:"flex",alignItems:"center",gap:7 }}>
                      <div style={{ fontSize:13,fontWeight:700,color:enabled?"#f0f4f8":"#64748b" }}>{store.name}</div>

                    </div>
                    <div style={{ fontSize:10,color:"#475569",marginTop:1 }}>{store.note}</div>
                  </div>
                </div>
                {/* toggle pill */}
                <div style={{ width:44,height:24,borderRadius:12,background:enabled?store.color:"rgba(255,255,255,.1)",position:"relative",transition:"background .2s",flexShrink:0 }}>
                  <div style={{ position:"absolute",top:3,left:enabled?22:3,width:18,height:18,borderRadius:"50%",background:"#fff",transition:"left .2s",boxShadow:"0 1px 4px rgba(0,0,0,.4)" }} />
                </div>
              </div>
            );
          })}
        </div>

        {disabledStores.size > 0 && (
          <div style={{ background:"rgba(251,191,36,.07)",border:"1px solid rgba(251,191,36,.2)",borderRadius:10,padding:"10px 14px",marginBottom:16,fontSize:11,color:"#fcd34d",lineHeight:1.6 }}>
            ⚠️ {disabledStores.size} store{disabledStores.size>1?"s":""} hidden. Prices from hidden stores won't appear in product cards or the basket.
          </div>
        )}

        <button onClick={onClose} style={{ width:"100%",padding:"13px",background:"linear-gradient(180deg,#4ade80 0%,#15803d 100%)",boxShadow:"0 3px 10px rgba(34,197,94,.5),inset 0 1px 0 rgba(255,255,255,.3)",border:"none",borderRadius:12,color:"#fff",cursor:"pointer",fontSize:14,fontWeight:700 }}>
          Done
        </button>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   SUBMIT PRICE MODAL — receipt-photo price submission
═══════════════════════════════════════════════════════════════════════════ */
function SubmitPriceModal({ onClose, lightMode=false }) {
  const [form,   setForm]   = useState({ name:"", mobile:"", email:"" });
  const [photo,  setPhoto]  = useState(null);  // { name, mimeType, base64 }
  const [status, setStatus] = useState("idle");
  const [photoError, setPhotoError] = useState("");
  const fileRef = useRef(null);

  const MAX_PHOTO_BYTES = 8 * 1024 * 1024; // 8MB — comfortably covers a phone photo

  const handlePhoto = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > MAX_PHOTO_BYTES) {
      setPhotoError("That photo's a bit large — please choose one under 8MB.");
      setPhoto(null);
      return;
    }
    setPhotoError("");
    const reader = new FileReader();
    reader.onload = (ev) => {
      const dataUrl = ev.target.result || "";
      const base64 = dataUrl.split(",")[1] || "";
      setPhoto({ name: file.name, mimeType: file.type || "image/jpeg", base64 });
    };
    reader.onerror = () => setPhotoError("Couldn't read that photo — please try again.");
    reader.readAsDataURL(file);
  };

  const handleSubmit = async () => {
    if (!photo) return;
    setStatus("sending");
    try {
      // Goes to a small Google Apps Script Web App (not Formspree — its free
      // tier doesn't allow file attachments), which saves the photo straight
      // into a Drive folder. text/plain avoids a CORS preflight the Apps
      // Script endpoint doesn't handle.
      const res = await fetch(RECEIPT_WEBAPP_URL, {
        method: "POST",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify({
          secret:        RECEIPT_SHARED_SECRET,
          name:          form.name,
          mobile:        form.mobile,
          email:         form.email,
          photoName:     photo ? photo.name : "",
          photoMimeType: photo ? photo.mimeType : "",
          photoBase64:   photo ? photo.base64 : "",
        })
      });
      const json = await res.json().catch(() => null);
      if (res.ok && json && json.ok) { setStatus("sent"); }
      else { setStatus("error"); }
    } catch { setStatus("error"); }
  };

  const required = !photo;

  return (
    <div style={{ position:"fixed",inset:0,zIndex:600,display:"flex",alignItems:"flex-end",justifyContent:"center",paddingTop:60,background:"rgba(0,0,0,.8)",backdropFilter:"blur(8px)" }}
      onClick={e=>{ if(e.target===e.currentTarget) onClose(); }}>
      <div style={{ width:"100%",maxWidth:520,background:lightMode?"rgba(255,252,248,.98)":"#120800",border:lightMode?"1px solid rgba(251,146,60,.35)":"1px solid rgba(251,146,60,.25)",borderRadius:"20px 20px 0 0",maxHeight:"88vh",display:"flex",flexDirection:"column" }}>

        {status==="sent" ? (
          <div style={{ textAlign:"center",padding:"30px 20px" }}>
            <div style={{ fontSize:48,marginBottom:14 }}>🏆</div>
            <div style={{ fontSize:18,fontWeight:700,color:"#fb923c",marginBottom:8 }}>Receipt submitted!</div>
            <div style={{ fontSize:12,color:lightMode?"#475569":"#94a3b8",lineHeight:1.8,marginBottom:24 }}>
              {form.name.trim() ? `Thanks ${form.name.trim().split(" ")[0]}! ` : "Thanks! "}We'll verify your receipt and add<br/>
              the prices to JerseyBasket within 24 hours.<br/>
              Thanks for helping keep it accurate! 🙌
            </div>
            <button onClick={onClose} style={{ padding:"11px 28px",background:"linear-gradient(180deg,#fb923c 0%,#b45309 100%)",boxShadow:"0 3px 10px rgba(194,65,12,.5),inset 0 1px 0 rgba(255,255,255,.25)",border:"none",borderRadius:11,color:"#fff",cursor:"pointer",fontSize:13,fontWeight:700 }}>
              Back to App
            </button>
          </div>
        ) : (
          <>
            {/* header */}
            <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",padding:"18px 20px 14px",borderBottom:`1px solid ${lightMode?"rgba(251,146,60,.25)":"rgba(251,146,60,.15)"}`,flexShrink:0 }}>
              <div>
                <div style={{ fontSize:17,fontWeight:700,color:lightMode?"#7c2d12":"#fed7aa" }}>📸 Submit a Receipt</div>
                <div style={{ fontSize:11,color:lightMode?"#92400e":"#9a3412",marginTop:2 }}>Help keep JerseyBasket's prices accurate</div>
              </div>
              <button onClick={onClose} style={{ background:lightMode?"rgba(0,0,0,.07)":"rgba(255,255,255,.07)",border:"none",borderRadius:7,width:32,height:32,color:lightMode?"#475569":"#94a3b8",cursor:"pointer",fontSize:16,flexShrink:0 }}>✕</button>
            </div>

            {/* scrollable body */}
            <div style={{ overflowY:"auto",padding:"16px 20px",paddingBottom:"calc(132px + 24px)",flex:1 }}>

              {/* name */}
              <div style={{ marginBottom:12 }}>
                <div style={{ fontSize:10,color:lightMode?"#7c2d12":"#9a3412",fontWeight:700,letterSpacing:".5px",marginBottom:6 }}>YOUR NAME <span style={{ color:lightMode?"#64748b":"#94a3b8",fontWeight:400 }}>(optional)</span></div>
                <input value={form.name} onChange={e=>setForm(p=>({...p,name:e.target.value}))} placeholder="First name, nickname or alias e.g. IslandShopper"
                  style={{ width:"100%",padding:"9px 12px",background:lightMode?"rgba(0,0,0,.05)":"rgba(255,255,255,.07)",border:lightMode?"1px solid rgba(0,0,0,.15)":"1px solid rgba(255,255,255,.11)",borderRadius:9,color:lightMode?"#0f172a":"#fff",fontSize:12,outline:"none",boxSizing:"border-box",fontFamily:"inherit" }} />
                <div style={{ fontSize:10,color:lightMode?"#475569":"#94a3b8",marginTop:4 }}>Any name or alias is fine — never shared or shown publicly</div>
              </div>

              {/* mobile */}
              <div style={{ marginBottom:12 }}>
                <div style={{ fontSize:10,color:lightMode?"#7c2d12":"#9a3412",fontWeight:700,letterSpacing:".5px",marginBottom:6 }}>MOBILE NUMBER <span style={{ color:lightMode?"#64748b":"#94a3b8",fontWeight:400 }}>(optional)</span></div>
                <input value={form.mobile} onChange={e=>setForm(p=>({...p,mobile:e.target.value}))} placeholder="e.g. 07797 123456"
                  style={{ width:"100%",padding:"9px 12px",background:lightMode?"rgba(0,0,0,.05)":"rgba(255,255,255,.07)",border:lightMode?"1px solid rgba(0,0,0,.15)":"1px solid rgba(255,255,255,.11)",borderRadius:9,color:lightMode?"#0f172a":"#fff",fontSize:12,outline:"none",boxSizing:"border-box",fontFamily:"inherit" }} />
              </div>

              {/* email */}
              <div style={{ marginBottom:16 }}>
                <div style={{ fontSize:10,color:lightMode?"#7c2d12":"#9a3412",fontWeight:700,letterSpacing:".5px",marginBottom:6 }}>EMAIL ADDRESS <span style={{ color:lightMode?"#64748b":"#94a3b8",fontWeight:400 }}>(optional)</span></div>
                <input value={form.email} onChange={e=>setForm(p=>({...p,email:e.target.value}))} placeholder="e.g. yourname@email.com"
                  style={{ width:"100%",padding:"9px 12px",background:lightMode?"rgba(0,0,0,.05)":"rgba(255,255,255,.07)",border:lightMode?"1px solid rgba(0,0,0,.15)":"1px solid rgba(255,255,255,.11)",borderRadius:9,color:lightMode?"#0f172a":"#fff",fontSize:12,outline:"none",boxSizing:"border-box",fontFamily:"inherit" }} />
                <div style={{ fontSize:10,color:lightMode?"#475569":"#94a3b8",marginTop:4 }}>Never shared or sold — only used if we need to check something with you</div>
              </div>

              {/* photo picker */}
              <div style={{ marginBottom:16 }}>
                <div style={{ fontSize:10,color:lightMode?"#7c2d12":"#9a3412",fontWeight:700,letterSpacing:".5px",marginBottom:8 }}>RECEIPT PHOTO <span style={{ color:"#f43f5e" }}>*</span></div>
                <input ref={fileRef} type="file" accept="image/*" onChange={handlePhoto} style={{ display:"none" }} />
                <button onClick={()=>fileRef.current?.click()}
                  style={{ width:"100%",padding:"14px",background:photo?`linear-gradient(180deg,#16a34a 0%,#14532d 100%)`:`linear-gradient(180deg,#fb923c 0%,#b45309 100%)`,border:"none",borderRadius:12,color:"#fff",cursor:"pointer",fontSize:14,fontWeight:700,boxShadow:photo?"0 3px 12px rgba(22,163,74,.5),inset 0 1px 0 rgba(255,255,255,.25)":"0 3px 12px rgba(194,65,12,.5),inset 0 1px 0 rgba(255,255,255,.25)",position:"relative",overflow:"hidden" }}>
                  <span style={{ position:"absolute",top:0,left:0,right:0,height:"52%",background:"linear-gradient(180deg,rgba(255,255,255,.25) 0%,rgba(255,255,255,.04) 100%)",borderRadius:"12px 12px 0 0",pointerEvents:"none" }}/>
                  {photo ? `✅ ${photo.name}` : "📷 Take / Choose Photo"}
                </button>
                {photo && (
                  <button onClick={()=>setPhoto(null)} style={{ width:"100%",marginTop:6,padding:"7px",background:"transparent",border:`1px solid ${lightMode?"rgba(0,0,0,.12)":"rgba(255,255,255,.1)"}`,borderRadius:8,color:lightMode?"#475569":"#64748b",cursor:"pointer",fontSize:11 }}>
                    ✕ Remove photo
                  </button>
                )}
                <div style={{ fontSize:10,color:lightMode?"#475569":"#94a3b8",marginTop:6,lineHeight:1.6 }}>
                  Make sure the store name, date and prices are clearly visible on the receipt.
                </div>
                {photoError && <div style={{ fontSize:11,color:"#fca5a5",marginTop:6 }}>{photoError}</div>}
              </div>

              {status==="error" && <div style={{ background:"rgba(239,68,68,.1)",border:"1px solid rgba(239,68,68,.28)",borderRadius:8,padding:"7px 12px",fontSize:11,color:"#fca5a5",marginBottom:12 }}>Something went wrong. Please email hello@jerseybasket.je</div>}

              <button onClick={handleSubmit} disabled={required||status==="sending"}
                style={{ width:"100%",padding:"13px",background:"linear-gradient(180deg,#fb923c 0%,#b45309 100%)",border:"none",borderRadius:12,color:"#fff",cursor:required?"not-allowed":"pointer",opacity:required||status==="sending"?0.6:1,fontSize:14,fontWeight:700,boxShadow:required||status==="sending"?"none":"0 3px 12px rgba(194,65,12,.6),inset 0 1px 0 rgba(255,255,255,.25)",position:"relative",overflow:"hidden" }}>
                <span style={{ position:"absolute",top:0,left:0,right:0,height:"52%",background:"linear-gradient(180deg,rgba(255,255,255,.25) 0%,rgba(255,255,255,.04) 100%)",borderRadius:"12px 12px 0 0",pointerEvents:"none" }}/>
                {status==="sending" ? "Submitting…" : "Submit Entry →"}
              </button>

            </div>{/* end scrollable body */}
          </>
        )}
      </div>
    </div>
  );
}


function AdBanner({ onEnquiry, externalPause }) {
  const PAUSE_MS  = 4000;
  const SLIDE_MS  = 620;

  // ── Single continuous loop through all 15 slides ──
  // A duplicate of slide 0 is appended to the end of the track so the
  // 15→1 wrap slides right-to-left exactly like every other transition,
  // then snaps invisibly back to the real slide 0 (which looks identical).
  const todayStr = new Date().toISOString().slice(0,10);
  const ACTIVE_SLIDES = AD_SLIDES.filter(s =>
    (!s.startDate || todayStr >= s.startDate) && (!s.endDate || todayStr <= s.endDate)
  );
  const COUNT     = ACTIVE_SLIDES.length;
  const DISPLAY_SLIDES = [...ACTIVE_SLIDES, ACTIVE_SLIDES[0]];
  const DISPLAY_COUNT  = DISPLAY_SLIDES.length;

  // ── Remember the last slide shown, so reopening the app doesn't always restart at slide 1 ──
  const getStartSlide = () => {
    try {
      const s = parseInt(localStorage.getItem("jb_ad_slide")||"0",10);
      return (isNaN(s)||s<0||s>=COUNT)?0:s;
    } catch(e) { return 0; }
  };
  const saveSlide = (i) => {
    try {
      localStorage.setItem("jb_ad_slide_test","1");
      localStorage.removeItem("jb_ad_slide_test");
      localStorage.setItem("jb_ad_slide",String(i));
    } catch(e) { /* storage unavailable — silently ignore */ }
  };

  const [current,  setCurrent]  = useState(() => getStartSlide());
  const [offset,   setOffset]   = useState(() => getStartSlide());   // 0..COUNT-1 (fractional during animation)
  const [paused,   setPaused]   = useState(false);
  const [progress, setProgress] = useState(0);
  const [panelOpen, setPanelOpen] = useState(false); // expandable offers panel (Silver/Gold/Platinum demo slides)

  const currentRef = useRef(getStartSlide());
  const timerRef   = useRef(null);
  const rafRef     = useRef(null);
  const pauseRef   = useRef(false);
  const startRef   = useRef(null);
  const animRef    = useRef(null); // rAF for slide animation

  const activeSlideData = ACTIVE_SLIDES[current];

  // ── GA4 event tracking for advertiser engagement — wrapped defensively
  // since gtag may not exist yet (blocked, still loading) and analytics
  // must never be able to break the click it's trying to measure ──
  const trackAdvertiserClick = (s, source, buttonLabel, url) => {
    try {
      if (window.gtag) {
        window.gtag('event', 'advertiser_click', {
          advertiser: s.advertiser || 'unknown',
          click_source: source, // 'banner_tap' | 'cta_button'
          button_label: buttonLabel || null,
          link_url: url,
        });
      }
    } catch (e) { /* never let analytics break the click */ }
  };

  // ── smooth slide to a target index ──────────────────────────────────────
  const slideTo = useCallback((target) => {
    cancelAnimationFrame(animRef.current);
    const from    = currentRef.current;
    const started = performance.now();
    // ease in-out cubic
    const ease = t => t < 0.5 ? 4*t*t*t : 1 - Math.pow(-2*t+2,3)/2;

    const step = (now) => {
      const t = Math.min((now - started) / SLIDE_MS, 1);
      setOffset(from + (target - from) * ease(t));
      if (t < 1) {
        animRef.current = requestAnimationFrame(step);
      } else if (target >= COUNT) {
        // Reached the duplicate wrap-slide (visually identical to slide 0) —
        // snap back to the real slide 0 invisibly so the loop continues seamlessly
        setOffset(0);
        setCurrent(0);
        currentRef.current = 0;
        saveSlide(0);
      } else {
        setOffset(target);
        setCurrent(target);
        currentRef.current = target;
        saveSlide(target);
      }
    };
    animRef.current = requestAnimationFrame(step);
  }, [COUNT]);

  // ── progress bar tick ────────────────────────────────────────────────────
  const startTick = useCallback(() => {
    cancelAnimationFrame(rafRef.current);
    setProgress(0);
    startRef.current = performance.now();
    const tick = (now) => {
      if (pauseRef.current) return;
      const frac = Math.min((now - startRef.current) / PAUSE_MS, 1);
      setProgress(frac);
      if (frac < 1) rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
  }, []);

  // ── schedule next advance — continuous forward loop through all 15 slides;
  //    slideTo() handles the seamless 15→1 wrap via the duplicate end-slide ──
  const schedule = useCallback((after = PAUSE_MS) => {
    clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => {
      if (pauseRef.current) return;
      slideTo(currentRef.current + 1);
      startTick();
      schedule();
    }, after);
  }, [slideTo, startTick]);

  // boot
  useEffect(() => {
    startTick();
    schedule();
    return () => {
      clearTimeout(timerRef.current);
      cancelAnimationFrame(rafRef.current);
      cancelAnimationFrame(animRef.current);
    };
  }, [schedule, startTick]);
  useEffect(() => {
    const handleVisibility = () => {
      if (document.visibilityState === "visible") {
        // Page is visible again — clear everything and restart cleanly
        pauseRef.current = false;
        setPaused(false);
        clearTimeout(timerRef.current);
        cancelAnimationFrame(rafRef.current);
        cancelAnimationFrame(animRef.current);
        startTick();
        schedule();
      } else {
        // Page hidden — pause everything to save resources
        clearTimeout(timerRef.current);
        cancelAnimationFrame(rafRef.current);
        cancelAnimationFrame(animRef.current);
      }
    };
    document.addEventListener("visibilitychange", handleVisibility);
    return () => document.removeEventListener("visibilitychange", handleVisibility);
  }, [startTick, schedule]);

  // ── pause while an external overlay (e.g. the Welcome screen) is open ──
  useEffect(() => {
    if (externalPause) {
      pauseRef.current = true;
      setPaused(true);
      clearTimeout(timerRef.current);
      cancelAnimationFrame(rafRef.current);
      cancelAnimationFrame(animRef.current);
    } else {
      pauseRef.current = false;
      setPaused(false);
      startTick();
      schedule();
    }
  }, [externalPause, startTick, schedule]);

  // hover pause / resume (also opens the expandable offers panel on demo slides)
  const handleEnter = () => {
    pauseRef.current = true;
    setPaused(true);
    clearTimeout(timerRef.current);
    cancelAnimationFrame(rafRef.current);
    if (ACTIVE_SLIDES[currentRef.current]?.panel) setPanelOpen(true);
  };
  const handleLeave = () => {
    pauseRef.current = false;
    setPaused(false);
    setPanelOpen(false);
    startTick();
    schedule();
  };

  // dot / swipe jump
  const jumpTo = useCallback((idx) => {
    clearTimeout(timerRef.current);
    cancelAnimationFrame(rafRef.current);
    slideTo(idx);
    startTick();
    schedule();
  }, [slideTo, startTick, schedule]);

  // touch swipe + tap-to-pause / second-tap-to-open
  const touchX        = useRef(0);
  const tapPaused     = useRef(false);
  const tapTimer      = useRef(null);
  const mouseDownX    = useRef(0);

  const handleTouchStart = (e) => {
    touchX.current = e.touches[0].clientX;
  };
  const handleTouchEnd = (e) => {
    const dx = e.changedTouches[0].clientX - touchX.current;
    if (Math.abs(dx) > 40) {
      // swipe
      tapPaused.current = false;
      pauseRef.current  = false;
      setPaused(false);
      setPanelOpen(false);
      jumpTo(dx < 0 ? (current+1)%COUNT : (current-1+COUNT)%COUNT);
      return;
    }
    // tap — prevent ghost click
    e.preventDefault();
    const s = ACTIVE_SLIDES[currentRef.current];
    if (!s) return;
    if (s.panel) {
      // DEMO SLIDE — tap toggles the expandable offers panel
      clearTimeout(tapTimer.current);
      if (!panelOpen) {
        tapPaused.current = true;
        pauseRef.current  = true;
        setPaused(true);
        setPanelOpen(true);
      } else {
        tapPaused.current = false;
        pauseRef.current  = false;
        setPaused(false);
        setPanelOpen(false);
        schedule(500);
        startTick();
      }
      return;
    }
    if (!tapPaused.current) {
      // FIRST TAP — pause so user can read
      tapPaused.current = true;
      pauseRef.current  = true;
      setPaused(true);
      clearTimeout(tapTimer.current);
      // auto-resume after 4s
      tapTimer.current = setTimeout(() => {
        tapPaused.current = false;
        pauseRef.current  = false;
        setPaused(false);
        schedule(500);
        startTick();
      }, 4000);
    } else {
      // SECOND TAP — open URL
      clearTimeout(tapTimer.current);
      tapPaused.current = false;
      pauseRef.current  = false;
      setPaused(false);
      if (s.link === ENQUIRY_TRIGGER) { onEnquiry(); }
      else { trackAdvertiserClick(s, 'banner_tap', null, s.link); window.open(s.link, "_blank", "noopener,noreferrer"); }
      schedule(500);
      startTick();
    }
  };

  // track translateX: offset=0 → 0%, offset=1 → -100%, etc. (against the display track, which includes the wrap-duplicate)
  const trackX = -(offset / DISPLAY_COUNT) * 100;

  return (
    <div onMouseEnter={handleEnter} onMouseLeave={handleLeave} style={{ position:"relative" }}>
    {/* Below this width the CTA block (flexShrink:0) leaves less room than the LEFT block
        (logo+eyebrow+headline, also flexShrink:0) needs — LEFT overflows rightward and paints
        underneath the CTAs instead of ever getting its own line. Force both onto their own
        full-width row on narrow screens so nothing overlaps.
        Note: flex-shrink:1 alone does nothing on a white-space:nowrap item — its min-content
        width still equals its full unshrunk width unless min-width:0 is also set. That gap is
        why the "Claim this slot" pitch slides (long eyebrow + long headline) still overflowed
        even after the row-level fix — the panel/real-advertiser slides just have short enough
        text to hide the same latent bug. */}
    <style>{`
      @media (max-width:640px){
        .jb-ad-outer{ max-height:188px !important; }
        .jb-ad-content{ flex-wrap:wrap; }
        .jb-ad-left{ flex-basis:100% !important; flex-wrap:wrap !important; row-gap:2px; }
        .jb-ad-headrow{ flex-basis:100% !important; flex-shrink:1 !important; min-width:0 !important; }
        .jb-ad-eyebrow{ flex-shrink:1 !important; min-width:0 !important; overflow:hidden; text-overflow:ellipsis; max-width:100%; }
        .jb-ad-headline{ min-width:0 !important; }
        .jb-ad-sub{ flex-basis:100% !important; white-space:normal !important; overflow:visible !important; text-overflow:clip !important; }
        .jb-ad-ctas{ flex-basis:100% !important; flex-wrap:wrap !important; row-gap:6px; }
      }
    `}</style>
    <div
      className="jb-ad-outer"
      data-allow-hswipe="true"
      onMouseDown={e=>{ mouseDownX.current = e.clientX; }}
      onClick={(e)=>{
        // Desktop click only — skip if touch (handled above)
        if(e.detail === 0) return;
        if(Math.abs(e.clientX - mouseDownX.current) > 5) return;
        const s = ACTIVE_SLIDES[current];
        if(!s) return;
        if(s.link===ENQUIRY_TRIGGER){ onEnquiry(); }
        else { trackAdvertiserClick(s, 'banner_tap', null, s.link); window.open(s.link,"_blank","noopener,noreferrer"); }
      }}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      style={{
        position:"relative",
        height:"auto", minHeight:72, maxHeight:130,
        paddingBottom:"env(safe-area-inset-bottom,0px)",
        paddingLeft:"env(safe-area-inset-left,0px)",
        paddingRight:"env(safe-area-inset-right,0px)",
        overflow:"hidden", touchAction:"pan-x",
        boxShadow:"0 -2px 16px rgba(0,0,0,0.35)",
        borderTop:"1px solid rgba(255,255,255,0.06)",
        cursor:"pointer",
      }}
    >
      {/* ── SLIDING TRACK ── all 15 slides + 1 duplicate wrap-slide sit side-by-side, track translates */}
      <div style={{
        display:"flex",
        width:`${DISPLAY_COUNT * 100}%`,
        transform:`translateX(${trackX}%)`,
        transition:"none",   /* animation is driven by rAF, not CSS */
        willChange:"transform",
      }}>
        {DISPLAY_SLIDES.map((s, i) => {
          /* Plain pitch slides (no ctaButtons, no panel) drop the separate "Claim this slot" CTA
             entirely — tapping the whole banner already opens the enquiry form, so it was a
             redundant duplicate click target and the main source of the mobile overflow fights.
             Panel slides (Silver/Gold/Platinum) also drop their "Tap or hover for info" CTA — same
             reasoning, the whole banner is already the interactive surface. Only real advertiser
             slides (ctaButtons) still show an explicit CTA. */
          const isPitchSlide = !s.ctaButtons && !s.panel;
          // Every slide type centres its text block now — pitch, panel, and real-advertiser alike.
          const shouldCenter = true;
          return (
          <div
            key={i === DISPLAY_SLIDES.length - 1 ? `${s.id}-wrap` : s.id}
            style={{
              width:`${100/DISPLAY_COUNT}%`,
              flexShrink:0,
              position:"relative",
              overflow:"hidden",
              background: s.bg,
              /* real advertiser slides render fully opaque — at .92 the near-black/saturated brand
                 backgrounds visibly wash out against the page behind; placeholders keep the original look */
              opacity: s.ctaButtons ? 1 : 0.92,
              display:"block",
              textDecoration:"none",
              /* verified advertiser slides get the same glossy 3D depth as the nav tabs / free-offer banner —
                 inset (not outer) shadow since this strip sits inside an overflow:hidden track and an outer
                 shadow would just get clipped */
              boxShadow: s.ctaButtons ? "inset 0 1px 0 rgba(255,255,255,.32), inset 0 -18px 26px -12px rgba(0,0,0,.62)" : "none",
            }}
          >
            {/* ── per-slide decorations ── */}
            {s.grid && (
              <div style={{ position:"absolute",inset:0,opacity:0.04,pointerEvents:"none",
                backgroundImage:"linear-gradient(#f59e0b 1px,transparent 1px),linear-gradient(90deg,#f59e0b 1px,transparent 1px)",
                backgroundSize:"40px 40px" }} />
            )}
            {s.deco && (
              <>
                <div style={{ position:"absolute",width:260,height:260,borderRadius:"50%",background:"rgba(74,222,128,0.07)",right:-50,top:-70,pointerEvents:"none" }} />
                <div style={{ position:"absolute",width:140,height:140,borderRadius:"50%",background:"rgba(74,222,128,0.07)",right:90,bottom:-45,pointerEvents:"none" }} />
              </>
            )}
            {s.cross && (
              <div style={{ position:"absolute",right:0,top:0,bottom:0,width:160,opacity:0.07,display:"flex",alignItems:"center",justifyContent:"center",pointerEvents:"none" }}>
                <div style={{ position:"relative",width:100,height:100 }}>
                  <div style={{ position:"absolute",top:"50%",left:0,right:0,height:30,background:"white",transform:"translateY(-50%)",borderRadius:4 }} />
                  <div style={{ position:"absolute",left:"50%",top:0,bottom:0,width:30,background:"white",transform:"translateX(-50%)",borderRadius:4 }} />
                </div>
              </div>
            )}
            {s.accent      && <div style={{ position:"absolute",top:0,left:0,right:0,height:3,background:s.accent,pointerEvents:"none" }} />}
            {s.accentBottom && <div style={{ position:"absolute",bottom:2,left:0,right:0,height:3,background:s.accentBottom,pointerEvents:"none" }} />}
            {/* glossy top sheen for verified advertiser slides — same recipe as the nav tabs / free-offer banner,
                layered on top of each advertiser's own bg gradient rather than replacing it */}
            {s.ctaButtons && (
              <span style={{ position:"absolute",top:0,left:0,right:0,height:"50%",background:"linear-gradient(180deg,rgba(255,255,255,.32) 0%,rgba(255,255,255,0) 100%)",pointerEvents:"none" }} />
            )}


            {/* ── CONTENT ── responsive: mobile stacks sub below eyebrow, desktop enlarges */}
            <div className="jb-ad-content" style={{
              position:"relative", zIndex:2,
              display:"flex", alignItems:"center", justifyContent:"space-between",
              padding:"clamp(10px,1.5vh,18px) clamp(10px,3vw,32px)",
              gap:"clamp(6px,2vw,20px)",
              maxWidth:1200, margin:"0 auto", boxSizing:"border-box",
              width:"100%",
            }}>
              {/* LEFT */}
              <div className="jb-ad-left" style={{ display:"flex", alignItems:"center", gap:"clamp(6px,1.5vw,16px)", minWidth:0, flex:1, flexWrap: (s.sub && s.sub.wrap) || isPitchSlide ? "wrap" : "nowrap", ...(shouldCenter ? { justifyContent:"center" } : {}) }}>
                {s.logo && <img src={s.logo} alt="advertiser logo" style={{ height:"clamp(32px,5.5vw,70px)", width:"auto", maxHeight:70, borderRadius:6, flexShrink:0, objectFit:"contain" }} />}
                {/* Eyebrow + headline row */}
                <div className="jb-ad-headrow" style={{ display:"flex", alignItems:"center", gap:"clamp(6px,1.2vw,14px)", flexShrink:0, ...(s.sub && s.sub.wrap ? { flexBasis:"auto" } : {}), ...(isPitchSlide ? { justifyContent:"center", flexWrap:"wrap", rowGap:2, flexBasis:"100%" } : shouldCenter ? { justifyContent:"center" } : {}) }}>
                  <div className="jb-ad-eyebrow" style={{ fontFamily:"'DM Sans',Arial,sans-serif", fontSize:"clamp(8px,1.4vw,13px)", fontWeight:700, letterSpacing:"1.5px", textTransform:"uppercase", color:s.eyebrow.color, borderLeft:`2px solid ${s.eyebrow.color}`, paddingLeft:6, lineHeight:1, whiteSpace:"nowrap", flexShrink:0, ...(isPitchSlide ? { flexBasis:"100%", textAlign:"center", borderLeft:"none", paddingLeft:0 } : {}) }}>
                    {s.eyebrow.text}
                  </div>
                  <div className="jb-ad-headline" style={{ fontFamily:"'DM Serif Display',Georgia,serif", fontSize:"clamp(13px,2.8vw,30px)", lineHeight:1.2, letterSpacing:"-0.3px", color:s.headline.headlineColor||"#f0f4f8", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis", ...(isPitchSlide ? { flexBasis:"100%", textAlign:"center" } : {}) }}>
                    {s.headline.before}
                    <span style={{
                      color: s.headline.highlightGold||s.headline.highlightGreen ? "transparent" : s.headline.highlightColor,
                      fontStyle:"italic",
                      textDecoration: s.headline.highlightUnderline ? "underline" : "none",
                      textUnderlineOffset:3, textDecorationThickness:1.5,
                      ...(s.headline.highlightGold  ? { background:"linear-gradient(90deg,#f59e0b,#fbbf24,#f59e0b)", WebkitBackgroundClip:"text", backgroundClip:"text" } : {}),
                      ...(s.headline.highlightGreen ? { background:"linear-gradient(135deg,#16a34a,#22c55e)",        WebkitBackgroundClip:"text", backgroundClip:"text" } : {}),
                    }}>{s.headline.highlight}</span>
                    {s.headline.after}
                  </div>
                </div>
                {/* Sub text — full-width centred row when wrap:true */}
                {s.sub && s.sub.text && (
                  <div className="jb-ad-sub" style={{ fontFamily:"'DM Sans',Arial,sans-serif", fontSize:"clamp(9px,1.3vw,15px)", color:s.sub.color, opacity:0.85, fontWeight:700, textDecoration:"underline", textDecorationThickness:1.5, textUnderlineOffset:2,
                    ...(s.sub.wrap ? {
                      flexBasis:"100%",
                      textAlign:"center",
                      padding:"2px clamp(8px,2vw,16px) 0",
                      whiteSpace:"normal",
                      lineHeight:1.3,
                      overflow:"hidden",
                      display:"-webkit-box",
                      WebkitLineClamp:2,
                      WebkitBoxOrient:"vertical",
                    } : {
                      whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis",
                      ...(shouldCenter ? { textAlign:"center" } : {}),
                      ...(isPitchSlide ? { flexBasis:"100%" } : {}),
                    })
                  }}>
                    {s.sub.text}
                  </div>
                )}
              </div>

              {/* RIGHT — CTA. Only real advertiser slides (ctaButtons) show one now; pitch and panel
                  slides rely on the whole banner already being tappable. Centered by default so any
                  future ctaButtons slide inherits the same treatment automatically. */}
              {s.ctaButtons && (
                <div className="jb-ad-ctas" style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:"clamp(6px,1vw,10px)", flexShrink:0 }}>
                  {s.ctaButtons.map((btn, bi) => (
                    <a
                      key={bi}
                      href={btn.href}
                      target={btn.href.startsWith("tel:") ? undefined : "_blank"}
                      rel={btn.href.startsWith("tel:") ? undefined : "noopener noreferrer"}
                      onClick={e=>{ e.stopPropagation(); trackAdvertiserClick(s, 'cta_button', btn.label, btn.href); }}
                      onTouchEnd={e=>e.stopPropagation()}
                      style={{
                        display:"flex", alignItems:"center", justifyContent:"center",
                        borderRadius:8, padding:"clamp(6px,1vh,10px) clamp(10px,1.4vw,18px)",
                        background:btn.bg, color:btn.color, border:`1px solid ${btn.border||"rgba(255,255,255,0.3)"}`,
                        fontFamily:"'DM Sans',Arial,sans-serif", fontSize:"clamp(10px,1.3vw,14px)", fontWeight:700,
                        textDecoration:"none", whiteSpace:"nowrap",
                      }}
                    >
                      {btn.label}
                    </a>
                  ))}
                </div>
              )}
            </div>
          </div>
          );
        })}
      </div>

      {/* ── progress bar ── */}
      <div style={{ position:"absolute",bottom:0,left:0,width:`${progress*100}%`,height:1.5,background:"rgba(255,255,255,0.35)",zIndex:10,pointerEvents:"none" }} />

      {/* ── dot indicators ── */}
      <div style={{ position:"absolute",bottom:5,right:"clamp(10px,2vw,20px)",display:"flex",gap:4,zIndex:10 }}>
        {ACTIVE_SLIDES.map((_,i) => (
          <div key={i} onClick={(e)=>{ e.stopPropagation(); jumpTo(i); }}
            style={{ width:i===current?10:4,height:4,borderRadius:i===current?2:50,
              background:i===current?"rgba(255,255,255,0.8)":"rgba(255,255,255,0.25)",
              cursor:"pointer",transition:"all 0.3s" }} />
        ))}
      </div>

      {/* ── paused hint ── */}
      {paused && (
        <div style={{ position:"absolute",top:5,right:"clamp(10px,2vw,20px)",fontFamily:"'DM Sans',Arial",fontSize:"9px",letterSpacing:"1px",textTransform:"uppercase",color:"rgba(255,255,255,0.55)",zIndex:10,display:"flex",alignItems:"center",gap:4 }}>
          <span style={{ opacity:0.6 }}>⏸</span>
          <span className="mobile-tap-hint" style={{ display:"none" }}>tap again to visit →</span>
        </div>
      )}
      <style>{`.mobile-tap-hint { display:none !important; } @media (pointer:coarse) { .mobile-tap-hint { display:inline !important; } }`}</style>
    </div>

    {/* ── EXPANDABLE OFFERS PANEL — Silver/Gold/Platinum demo slides only ── */}
    {panelOpen && activeSlideData?.panel && (
      <div
        style={{
          position:"absolute", left:0, right:0, bottom:"100%",
          height: `min(${ {quarter:"25vh", half:"42vh", full:"58vh"}[activeSlideData.panel.size] || "42vh" }, calc(100dvh - 160px))`,
          maxHeight: `min(${ {quarter:220, half:360, full:480}[activeSlideData.panel.size] || 360 }px, calc(100dvh - 160px))`,
          background:"rgba(8,13,26,0.98)",
          backdropFilter:"blur(12px)",
          borderTop:`3px solid ${activeSlideData.panel.accent}`,
          boxShadow:"0 -8px 32px rgba(0,0,0,0.5)",
          zIndex:150,
          overflowY:"auto",
          padding:"20px 24px",
          display:"flex", flexDirection:"column",
        }}
      >
        {(() => {
          const DEMO_INDICES = [2, 7, 12]; // Silver, Gold, Platinum slide indices
          const demoPos  = DEMO_INDICES.indexOf(current);
          const prevIdx  = demoPos > 0 ? DEMO_INDICES[demoPos - 1] : null;
          const nextIdx  = demoPos >= 0 && demoPos < DEMO_INDICES.length - 1 ? DEMO_INDICES[demoPos + 1] : null;
          const prevTier = prevIdx !== null ? ACTIVE_SLIDES[prevIdx]?.panel?.tier : null;
          const nextTier = nextIdx !== null ? ACTIVE_SLIDES[nextIdx]?.panel?.tier : null;
          return (prevTier || nextTier) && (
            <div style={{ display:"flex", justifyContent:"space-between", marginBottom:10 }}>
              {prevTier ? (
                <button onClick={()=>slideTo(prevIdx)} style={{ background:"#334155", border:"1px solid rgba(255,255,255,0.25)", borderRadius:8, padding:"7px 14px", color:"#ffffff", fontSize:12.5, fontWeight:700, cursor:"pointer" }}>
                  ← {prevTier}
                </button>
              ) : <span />}
              {nextTier && (
                <button onClick={()=>slideTo(nextIdx)} style={{ background:"#334155", border:"1px solid rgba(255,255,255,0.25)", borderRadius:8, padding:"7px 14px", color:"#ffffff", fontSize:12.5, fontWeight:700, cursor:"pointer" }}>
                  {nextTier} →
                </button>
              )}
            </div>
          );
        })()}
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:12 }}>
          <div>
            <div style={{ fontSize:11, fontWeight:700, letterSpacing:1, textTransform:"uppercase", color:activeSlideData.panel.accent }}>
              {activeSlideData.panel.tier} Package
            </div>
            <div style={{ fontSize:22, fontWeight:800, color:"#ffffff", marginTop:2 }}>
              {activeSlideData.panel.price}
            </div>
          </div>
          <button
            onClick={()=>{ setPanelOpen(false); pauseRef.current=false; setPaused(false); schedule(500); startTick(); }}
            style={{ background:"rgba(255,255,255,0.1)", border:"none", borderRadius:8, width:28, height:28, color:"#fff", fontSize:16, cursor:"pointer", lineHeight:1 }}
          >×</button>
        </div>
        <div style={{ flex:1 }}>
          {activeSlideData.panel.bullets.map((b,i) => (
            <div key={i} style={{ display:"flex", gap:8, alignItems:"flex-start", marginBottom:8 }}>
              <span style={{ color:activeSlideData.panel.accent, fontSize:13, marginTop:1 }}>✓</span>
              <span style={{ fontSize:13, color:"#e2e8f0", lineHeight:1.4 }}>{b}</span>
            </div>
          ))}
        </div>
        <button
          onClick={()=>{ setPanelOpen(false); pauseRef.current=false; setPaused(false); onEnquiry(); }}
          style={{
            marginTop:12, background:activeSlideData.panel.accent, color:"#1e1e1e", border:"none",
            borderRadius:10, padding:"11px 20px", fontSize:13, fontWeight:700, cursor:"pointer", alignSelf:"flex-start",
          }}
        >Get in touch about {activeSlideData.panel.tier}</button>
      </div>
    )}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   BASKET ITEM — swipe to delete on mobile, ✕ button on desktop, tick off
═══════════════════════════════════════════════════════════════════════════ */
function BasketItem({ item, overPay, onRemove, onAdd, onDelete, ticked=false, onToggleTicked, lightMode=false }) {
  const [swipeX,     setSwipeX]     = useState(0);
  const [swiping,    setSwiping]    = useState(false);
  const [deleted,    setDeleted]    = useState(false);
  const startX = useRef(0);
  const SWIPE_THRESHOLD = 80;

  const handleTouchStart = (e) => {
    startX.current = e.touches[0].clientX;
    setSwiping(true);
  };

  const handleTouchMove = (e) => {
    const dx = e.touches[0].clientX - startX.current;
    // Only allow left swipe (negative dx)
    if (dx < 0) setSwipeX(Math.max(dx, -120));
  };

  const handleTouchEnd = () => {
    setSwiping(false);
    if (swipeX < -SWIPE_THRESHOLD) {
      // Trigger delete animation
      setDeleted(true);
      setTimeout(onDelete, 300);
    } else {
      setSwipeX(0);
    }
  };

  if (deleted) return null;

  return (
    <div style={{ position:"relative", overflow:"hidden", borderRadius:12 }}>
      {/* Red delete background revealed on swipe */}
      <div style={{
        position:"absolute", right:0, top:0, bottom:0, width:120,
        background:"linear-gradient(135deg,#dc2626,#b91c1c)",
        display:"flex", alignItems:"center", justifyContent:"center",
        borderRadius:12, gap:6,
      }}>
        <span style={{ fontSize:22 }}>🗑️</span>
      </div>

      {/* Main item row */}
      <div
        data-allow-hswipe="true"
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        style={{
          display:"flex", alignItems:"center", justifyContent:"space-between",
          background: ticked ? (lightMode?"#dcfce7":"#0d2818") : (lightMode?"#f8fafc":"#0f172a"),
          borderRadius:12, padding:"9px 13px", touchAction:"pan-x",
          border: ticked ? "1px solid rgba(34,197,94,.2)" : lightMode?"1px solid rgba(0,0,0,.1)":"1px solid rgba(255,255,255,.07)",
          transform:`translateX(${swipeX}px)`,
          transition: swiping ? "none" : "transform .3s ease, background .2s, border .2s, opacity .3s",
          opacity: deleted ? 0 : 1,
          position:"relative", zIndex:1,
          userSelect:"none",
        }}
      >
        {/* Tick off button */}
        <button
          onClick={onToggleTicked}
          title={ticked ? "Mark as not collected" : "Mark as collected"}
          style={{
            flexShrink:0, width:24, height:24, borderRadius:6,
            background: ticked ? "#16a34a" : lightMode?"rgba(0,0,0,.04)":"rgba(255,255,255,.08)",
            border: ticked ? "none" : lightMode?"1.5px solid rgba(0,0,0,.28)":"1px solid rgba(255,255,255,.15)",
            color:"white", cursor:"pointer", fontSize:12, fontWeight:700,
            display:"flex", alignItems:"center", justifyContent:"center",
            marginRight:8, transition:"all .2s",
          }}>
          {ticked ? "✓" : ""}
        </button>

        {/* Product info */}
        <div style={{ display:"flex", alignItems:"center", gap:8, flex:1, minWidth:0 }}>
          <span style={{ fontSize:18, flexShrink:0, opacity: ticked ? 0.4 : 1, transition:"opacity .2s" }}>{item.product.icon}</span>
          <div style={{ minWidth:0 }}>
            <Tooltip text={item.product.name}>
              <div style={{ fontSize:11.5, fontWeight:600, color: ticked ? "#475569" : lightMode?"#0f172a":"#f0f4f8", textDecoration: ticked ? "line-through" : "none", transition:"all .2s" }}>
                {item.product.name}
              </div>
            </Tooltip>
            <div style={{ fontSize:9.5, color:"#475569" }}>
              {item.store?.emoji} {item.store?.name} · £{item.price.toFixed(2)}
              {overPay>0.01&&<span style={{ color:"#f87171", marginLeft:4 }}>(+£{overPay.toFixed(2)} vs cheapest)</span>}
            </div>
          </div>
        </div>

        {/* Quantity controls + price + delete */}
        <div style={{ display:"flex", flexDirection:"column", alignItems:"flex-end", gap:4, flexShrink:0 }}>
          <span style={{ fontSize:12.5, fontWeight:700, color: ticked ? "#475569" : lightMode?"#0f172a":"#f0f4f8", textDecoration: ticked ? "line-through" : "none" }}>
            £{(item.price*item.qty).toFixed(2)}
          </span>
          <div style={{ display:"flex", alignItems:"flex-start", gap:5 }}>
            <div style={{ display:"flex", alignItems:"center", gap:5, background:lightMode?"rgba(0,0,0,.06)":"rgba(255,255,255,.06)", borderRadius:8, padding:"3px 7px" }}>
              <button onClick={onRemove} style={{ background:lightMode?"#fff":"rgba(255,255,255,.9)", border:lightMode?"1px solid rgba(0,0,0,.15)":"none", borderRadius:5, width:20, height:20, color:"#dc2626", cursor:"pointer", fontSize:14, fontWeight:700, lineHeight:1, display:"flex", alignItems:"center", justifyContent:"center" }}>−</button>
              <span style={{ fontSize:12, fontWeight:700, minWidth:16, textAlign:"center", color:lightMode?"#0f172a":"#f0f4f8" }}>{item.qty}</span>
              <button onClick={onAdd} style={{ background:lightMode?"#fff":"rgba(255,255,255,.9)", border:lightMode?"1px solid rgba(0,0,0,.15)":"none", borderRadius:5, width:20, height:20, color:"#16a34a", cursor:"pointer", fontSize:14, fontWeight:700, lineHeight:1, display:"flex", alignItems:"center", justifyContent:"center" }}>+</button>
            </div>
            {/* ✕ delete button */}
            <button
              onClick={()=>{ setDeleted(true); setTimeout(onDelete, 300); }}
              title="Remove item"
              style={{ background:"rgba(255,255,255,.9)", border:"1px solid rgba(239,68,68,.3)", borderRadius:6, width:22, height:22, color:"#dc2626", cursor:"pointer", fontSize:11, fontWeight:700, display:"flex", alignItems:"center", justifyContent:"center", transition:"all .15s", flexShrink:0 }}
              onMouseEnter={e=>{ e.currentTarget.style.background="rgba(255,255,255,1)"; e.currentTarget.style.borderColor="rgba(239,68,68,.7)"; }}
              onMouseLeave={e=>{ e.currentTarget.style.background="rgba(255,255,255,.9)"; e.currentTarget.style.borderColor="rgba(239,68,68,.3)"; }}
            >✕</button>
          </div>
        </div>
      </div>

      {/* Swipe hint — only shows briefly on first render on mobile */}
      {swipeX < -10 && (
        <div style={{ position:"absolute", bottom:4, right:10, fontSize:9, color:"rgba(255,255,255,.3)" }}>
          Keep swiping to remove
        </div>
      )}
    </div>
  );
}

function Chip({ active, onClick, color, children, lightMode=false }) {
  const hexToRgb = (hex) => {
    const r = parseInt(hex.slice(1,3),16);
    const g = parseInt(hex.slice(3,5),16);
    const b = parseInt(hex.slice(5,7),16);
    return {r,g,b};
  };
  const {r,g,b} = hexToRgb(color);
  const light = `rgb(${Math.min(255,r+40)},${Math.min(255,g+40)},${Math.min(255,b+40)})`;
  const dark  = `rgb(${Math.round(r*0.55)},${Math.round(g*0.55)},${Math.round(b*0.55)})`;
  const dim   = `rgb(${Math.round(r*0.25)},${Math.round(g*0.25)},${Math.round(b*0.25)})`;
  const inactiveText = lightMode
    ? `rgb(${Math.max(0,r-60)},${Math.max(0,g-60)},${Math.max(0,b-60)})`
    : `rgba(${r+80},${g+80},${b+80},0.85)`;
  return (
    <button onClick={onClick} style={{
      whiteSpace:"nowrap", padding:"6px 13px", borderRadius:22, fontSize:11, fontWeight:700, cursor:"pointer",
      background: active
        ? `linear-gradient(180deg,${light} 0%,${dark} 100%)`
        : lightMode ? `rgba(${r},${g},${b},0.15)` : `linear-gradient(180deg,${dark} 0%,${dim} 100%)`,
      border: `1px solid rgba(${r},${g},${b},${active?0.7:lightMode?0.5:0.35})`,
      color: active ? "#fff" : inactiveText,
      boxShadow: active
        ? `0 3px 10px rgba(${r},${g},${b},0.55), inset 0 1px 0 rgba(255,255,255,0.25)`
        : `0 2px 6px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.07)`,
      textShadow: "0 1px 2px rgba(0,0,0,0.35)",
      position:"relative", overflow:"hidden",
      opacity: active ? 1 : 0.9,
    }}>
      <span style={{ position:"absolute", top:0, left:0, right:0, height:"52%", background:"linear-gradient(180deg,rgba(255,255,255,0.28) 0%,rgba(255,255,255,0.04) 100%)", borderRadius:"22px 22px 0 0", pointerEvents:"none" }} />
      {children}
    </button>
  );
}

